INSERT INTO dataset_info VALUES('dataset','SIMULATED demo data. Not real astronaut data.');
INSERT INTO dataset_info VALUES('scenario','14 days quiet baseline (2026-10-25..11-07), SPE ramp from 2026-11-08 14:00, peak ~S3 2026-11-09 02:00, recovery through 11-12.');
INSERT INTO dataset_info VALUES('effect_size_note','Health responses are exaggerated to demonstrate detection. A few mSv would not cause measurable lymphopenia or nausea in reality.');
INSERT INTO dataset_info VALUES('dose_note','Dose rates are illustrative placeholders, not calibrated to any spacecraft.');
INSERT INTO dataset_info VALUES('flux_units','pfu = particles/(cm2 s sr), protons >= 10 MeV; NOAA S1 >= 10, S2 >= 100, S3 >= 1000 pfu.');
INSERT INTO dataset_info VALUES('baseline_note','Baselines use the in-flight window before the event; a real system should prefer pre-flight data.');
